import {
	ApartmentOutlined,
	DashboardOutlined,
	DatabaseOutlined,
	FileOutlined,
	ForkOutlined,
	FundProjectionScreenOutlined,
	HistoryOutlined,
	LogoutOutlined,
	RobotOutlined,
	SendOutlined,
	SettingOutlined,
	UnorderedListOutlined,
	UserOutlined,
} from "@ant-design/icons";
import { Avatar, Dropdown, Grid, Layout, Menu, Typography } from "antd";
import type { ReactNode } from "react";
import { useEffect } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "../hooks/useAuth";
import BuildVersionBadge from "./BuildVersionBadge";
import CmdKSearch from "./CmdKSearch";

const { Sider, Content } = Layout;
const { useBreakpoint } = Grid;

// Visually hidden but accessible to screen readers
const srOnlyStyle: React.CSSProperties = {
	position: "absolute",
	width: 1,
	height: 1,
	padding: 0,
	margin: -1,
	overflow: "hidden",
	clip: "rect(0, 0, 0, 0)",
	whiteSpace: "nowrap",
	borderWidth: 0,
};

const menuItems = [
	{ key: "/dashboard", icon: <DashboardOutlined />, label: "概览" },
	{ type: "divider" as const },
	{ key: "/assets", icon: <DatabaseOutlined />, label: "资产管理" },
	{ key: "/mcap-files", icon: <FileOutlined />, label: "MCAP 文件" },
	{ type: "divider" as const },
	{ key: "/deliveries", icon: <SendOutlined />, label: "交付管理" },
	{ key: "/events", icon: <UnorderedListOutlined />, label: "事件流" },
	{ type: "divider" as const },
	{ key: "/algo-runs", icon: <HistoryOutlined />, label: "运行记录" },
	{ key: "/algo", icon: <RobotOutlined />, label: "算法处理" },
	{ type: "divider" as const },
	{ key: "/pipeline", icon: <ForkOutlined />, label: "流水线" },
	{ type: "divider" as const },
	{ key: "/registry", icon: <ApartmentOutlined />, label: "注册中心" },
	{
		key: "/metrics",
		icon: <FundProjectionScreenOutlined />,
		label: "指标检索",
	},
	{ key: "/settings", icon: <SettingOutlined />, label: "设置" },
];

function resolveSelectedKey(pathname: string): string {
	if (pathname.startsWith("/dashboard")) return "/dashboard";
	if (pathname.startsWith("/assets")) return "/assets";
	if (pathname.startsWith("/metrics")) return "/metrics";
	if (pathname.startsWith("/deliveries")) return "/deliveries";
	if (pathname.startsWith("/mcap-files")) return "/mcap-files";
	if (pathname.startsWith("/events")) return "/events";
	if (pathname.startsWith("/settings")) return "/settings";
	if (pathname.startsWith("/registry")) return "/registry";
	if (pathname.startsWith("/pipeline")) return "/pipeline";
	if (pathname.startsWith("/workflows")) return "/pipeline";
	if (pathname.startsWith("/algo-runs")) return "/algo-runs";
	if (pathname.startsWith("/algorithms")) return "/algo";
	if (pathname.startsWith("/algo")) return "/algo";
	return "/assets";
}

function isFullBleedPage(pathname: string): boolean {
	return pathname.startsWith("/pipeline");
}

export default function AppLayout({ children }: { children: ReactNode }) {
	const navigate = useNavigate();
	const location = useLocation();
	const { logout } = useAuth();
	const screens = useBreakpoint();
	const isMobile = !screens.lg;
	const siderWidth = 220;
	const fullBleed = isFullBleedPage(location.pathname);

	// Browser restores scroll position on back-nav, no dep needed
	useEffect(() => {
		window.scrollTo(0, 0);
	}, []);

	return (
		<Layout style={{ minHeight: "100vh" }}>
			<h1 style={srOnlyStyle}>Cyber Databrew</h1>
			<Sider
				width={siderWidth}
				breakpoint="lg"
				collapsedWidth={0}
				trigger={null}
				style={{
					overflow: "auto",
					height: "100vh",
					position: "fixed",
					left: 0,
					top: 0,
					bottom: 0,
					zIndex: 100,
				}}
			>
				{/* logo area */}
				<button
					type="button"
					style={{
						height: 64,
						display: "flex",
						alignItems: "center",
						paddingLeft: 24,
						cursor: "pointer",
						background: "none",
						border: "none",
						width: "100%",
					}}
					onClick={() => navigate("/dashboard")}
				>
					<img
						src="/argo/assets/images/logo.png"
						alt="DataBrew"
						style={{ width: 28, height: 28, marginRight: 10 }}
					/>
					<Typography.Title level={5} style={{ margin: 0, color: "#fff" }}>
						DataBrew
					</Typography.Title>
				</button>

				{/* search */}
				<div style={{ padding: "0 16px 12px" }}>
					<CmdKSearch />
				</div>

				{/* nav */}
				<Menu
					theme="dark"
					mode="inline"
					selectedKeys={[resolveSelectedKey(location.pathname)]}
					items={menuItems}
					onClick={({ key }) => navigate(key)}
				/>
				{!isMobile ? <BuildVersionBadge variant="sidebar" /> : null}
			</Sider>
			<Layout style={{ marginLeft: isMobile ? 0 : siderWidth }}>
				<Content style={{ minHeight: "100vh" }}>
					<div
						style={{
							display: "flex",
							justifyContent: "flex-end",
							padding: "12px 24px",
							background: "#fff",
							borderBottom: "1px solid #f0f0f0",
						}}
					>
						<Dropdown
							menu={{
								items: [
									{
										key: "logout",
										icon: <LogoutOutlined />,
										label: "退出登录",
										onClick: () => {
											logout();
											navigate("/login");
										},
									},
								],
							}}
							placement="bottomRight"
						>
							<Avatar
								size="small"
								icon={<UserOutlined />}
								style={{ cursor: "pointer", backgroundColor: "#1677ff" }}
							/>
						</Dropdown>
					</div>
					<div
						style={{
							padding: fullBleed ? 0 : 24,
							minHeight: fullBleed ? 0 : undefined,
						}}
					>
						{children}
					</div>
				</Content>
			</Layout>
			{isMobile ? <BuildVersionBadge offsetLeft={8} /> : null}
		</Layout>
	);
}
