import { Button, Result } from "antd";
import type { ErrorInfo, ReactNode } from "react";
import { Component } from "react";

interface Props {
	children: ReactNode;
	title?: string;
	subTitle?: string;
}

interface State {
	hasError: boolean;
	error: Error | null;
}

function isChunkLoadError(error: Error | null) {
	if (!error) return false;
	return /Failed to fetch dynamically imported module|Importing a module script failed|Loading chunk|MIME type/i.test(
		error.message,
	);
}

export default class ErrorBoundary extends Component<Props, State> {
	constructor(props: Props) {
		super(props);
		this.state = { hasError: false, error: null };
	}

	static getDerivedStateFromError(error: Error): State {
		return { hasError: true, error };
	}

	componentDidCatch(error: Error, errorInfo: ErrorInfo) {
		console.error("ErrorBoundary caught:", error, errorInfo);
	}

	handleRetry = () => {
		this.setState({ hasError: false, error: null });
	};

	render() {
		if (this.state.hasError) {
			const chunkLoadError = isChunkLoadError(this.state.error);
			const title =
				this.props.title ?? (chunkLoadError ? "页面资源已更新" : "页面出错了");
			const subTitle =
				this.props.subTitle ??
				(chunkLoadError
					? "当前浏览器标签页仍在使用旧版本入口，请刷新页面后继续。"
					: (this.state.error?.message ?? "未知错误"));
			return (
				<Result
					status="error"
					title={title}
					subTitle={subTitle}
					extra={[
						<Button
							key="reload"
							type="primary"
							onClick={() => window.location.reload()}
						>
							刷新页面
						</Button>,
						...(chunkLoadError
							? []
							: [
									<Button key="retry" onClick={this.handleRetry}>
										重试
									</Button>,
								]),
					]}
				/>
			);
		}
		return this.props.children;
	}
}
